const __pageData = JSON.parse('{"title":"11. Provider & Model System","description":"","frontmatter":{},"headers":[],"relativePath":"spec/03-runtime/11-provider-model-system.md","filePath":"spec/03-runtime/11-provider-model-system.md","lastUpdated":1790052354000}');
